{"status":"edit","missing_fact":"","edits":[{"path":"service.hpp","hash":"6801c7084ec4b1c51f79d5494436f7971050011ed6e63a7b6e2bdd6d5a7e7b31","old":"inline std::string csvField(const std::string& s){return "\""+s+"\"";}","new":"inline std::string csvField(const std::string& s){
    std::string result = "\"";
    for (char c : s) {
        if (c == '"') result.push_back('"');
        result.push_back(c);
    }
    result.push_back('"');
    return result;
}"}]}
